    "population", "height", "weight", "length", "area", "distance", "speed",
    "percentage", "percent", "age", "clause", "phrase", "sentence",
    "description", "quote", "statement", "definition", "explanation", "reason",
}

_TITLE_WORK_TERMS = {
    "title", "name", "who", "author", "director", "actor", "actress",
    "president", "founder", "inventor", "player", "umpire", "referee",
    "film", "movie", "book", "novel", "song", "album", "play",
    "musical", "show", "series", "painting", "sculpture", "poem",
}

_DATE_NUMERIC_TERMS = {
    "date", "year", "day", "month", "amount", "number", "score", "population",
    "height", "weight", "length", "area", "distance", "speed", "percentage",
    "percent", "age",
}

_CLAUSE_TERMS = {
    "clause", "phrase", "sentence", "description", "quote", "statement",
    "definition", "explanation", "reason",
}

_TOKEN_RE = re.compile(r"[A-Za-z0-9]+(?:[.'\u2019\-][A-Za-z0-9]+)*")

_TITLE_EXPANSION_STOP_WORDS = {
    "context", "question", "answer", "passage", "excerpt", "document",
    "text", "paragraph", "source", "statement", "summary", "article",
}


def _norm_for_match(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", " ", value.lower()).strip()


def _text_contains_norm(text: str, fragment: str) -> bool:
    fragment = (fragment or "").strip()
    if not fragment:
        return False
    return _norm_for_match(fragment) in _norm_for_match(text)


def _tokenize_spans(text: str) -> list[dict]:
    tokens: list[dict] = []
    for match in _TOKEN_RE.finditer(text or ""):
        token = match.group()
        tokens.append(
            {
                "start": match.start(),
                "end": match.end(),
                "text": token,
                "norm": token.lower(),
            }
        )
    return tokens


def _strip_wrapper_formatting(text: str) -> str:
    value = (text or "").strip()
    if value.startswith("```"):
        value = re.sub(r"^```[^\n]*\n?", "", value)
        value = re.sub(r"\n?```$", "", value)
        value = value.strip()

    lines = value.splitlines()
    if any(re.match(r"^\s*>", line) for line in lines):
        lines = [re.sub(r"^\s*> ?", "", line) for line in lines]
        value = "\n".join(lines).strip()

    non_empty = [line for line in value.splitlines() if line.strip()]
    if non_empty and all(
        re.match(r"^\s*(?:[-*+]|\d+[.)])\s+", line) for line in non_empty
    ):
        value = "\n".join(
            re.sub(r"^\s*(?:[-*+]|\d+[.)])\s+", "", line)
            for line in value.splitlines()
        ).strip()

    value = re.sub(r"\*\*(.+?)\*\*", r"\1", value)
    value = re.sub(r"__(.+?)__", r"\1", value)

    while len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'`":
        value = value[1:-1].strip()

    return value.strip()


def _strip_sentence_prefixes(text: str) -> str:
    value = (text or "").strip()
    for _ in range(5):
        before = value
        for pattern in _ANSWER_PREFIX_PATTERNS:
            value = re.sub(pattern, "", value, count=1, flags=re.IGNORECASE).strip()
            if value != before:
                break
        if value == before:
            break
    return value


def _strip_terminal_punctuation(text: str) -> str:
    value = (text or "").strip()
    while value:
        if value[-1] in ".,;:!?\u2026":
            value = value[:-1].rstrip()
        elif value[-1] in "\"'`":
            value = value[:-1].rstrip()
        else:
            break
    return value.strip()


def _split_segments(text: str) -> list[str]:
    value = (text or "").strip()
    if not value:
        return []
    parts = re.split(r"(?<=[.!?])\s+", value)
    segments: list[str] = []
    for part in parts:
        for sub in re.split(r"\n+", part):
            sub = sub.strip()
            if sub:
                segments.append(sub)
    return segments or [value]


def _question_query(question: str) -> str:
    value = (question or "").strip()
    qpos = value.rfind("?")
    if qpos == -1:
        return value
    start = 0
    for pos in range(qpos - 1, -1, -1):
        if value[pos] in ".!?\n":
            start = pos + 1
            break
    return value[start:qpos + 1].strip()


def _query_has_any(query: str, terms: set[str]) -> bool:
    lowered = (query or "").lower()
    return any(
        re.search(r"\b" + re.escape(term) + r"\b", lowered) for term in terms
    )


def _singularize(word: str) -> str:
    value = (word or "").lower()
    if value.endswith("ies") and len(value) > 4:
        return value[:-3] + "y"
    if value.endswith("es") and len(value) > 3:
        return value[:-2]
    if value.endswith("s") and not value.endswith("ss"):
        return value[:-1]
    return value


def _strip_leading_locative(text: str, query: str, context: str) -> str:
    value = (text or "").strip()
    if not _query_has_any(query, _LOCATIVE_QUERY_WORDS):
        return value
    match = re.match(r"(?i)^(on|in|at|from|to)\s+(.+)$", value)
    if not match:
        return value
    remainder = match.group(2).strip()
    if remainder and _text_contains_norm(context, remainder):
        return remainder
    return value


def _strip_trailing_category(text: str, query: str, context: str) -> str:
    value = (text or "").strip()
    tokens = _tokenize_spans(value)
    if len(tokens) < 2:
        return value
    terms = sorted(
        (term for term in _CATEGORY_TERMS if re.search(r"\b" + re.escape(term) + r"\b", (query or "").lower())),
        key=len,
        reverse=True,
    )
    for term in terms:
        last_norm = tokens[-1]["norm"]
        if _singularize(last_norm) != term:
            continue
        body = value[: tokens[-1]["start"]].strip()
        if not body:
            continue
        if _text_contains_norm(context, value):
            return value
        if _text_contains_norm(context, body):
            return body
    return value


def _window_for_tokens(seg_tokens: list[dict], cand_norms: list[str]):
    if not seg_tokens or not cand_norms:
        return None
    seg_norms = [token["norm"] for token in seg_tokens]
    n = len(seg_tokens)
    m = len(cand_norms)
    if m <= n:
        for start in range(n - m + 1):
            if seg_norms[start:start + m] == cand_norms:
                return start, start + m, "exact"
    positions: list[int] = []
    search_from = 0
    for cand in cand_norms:
        found = -1
        for pos in range(search_from, n):
            if seg_norms[pos] == cand:
                found = pos
                break
        if found == -1:
            return None
        positions.append(found)
        search_from = found + 1
    return positions[0], positions[-1] + 1, "gapped"


def _expand_context_window(
    segment: str, seg_tokens: list[dict], start_idx: int, end_idx: int, query: str
) -> str:
    if not seg_tokens or end_idx <= start_idx:
        return ""
    start = seg_tokens[start_idx]["start"]
    end = seg_tokens[end_idx - 1]["end"]
    after = segment[end:]

    if _query_has_any(query, _TITLE_WORK_TERMS):
        left_idx = start_idx - 1
        while left_idx >= 0:
            token = seg_tokens[left_idx]
            word = token["text"]
            if word.lower() in {"the", "a", "an"}:
                left_idx -= 1
                continue
            if word.lower() in _TITLE_EXPANSION_STOP_WORDS:
                break
            if word and word[0].isupper():
                left_idx -= 1
                continue
            break
        if left_idx + 1 < start_idx:
            start = seg_tokens[left_idx + 1]["start"]

        title_after = segment[end:]
        subtitle = re.match(
            r"\s*(?::\s+.*?)(?=\s+(?:is|was|has|had|by|in|on|at|from|to)\b|\.|,|;|$)",
            title_after,
        )
        if subtitle:
            end += subtitle.end()
        else:
            parenthetical = re.match(r"\s*(\([^)]*\)|\[[^\]]*\])", title_after)
            if parenthetical:
                end += parenthetical.end()

    if _query_has_any(query, _DATE_NUMERIC_TERMS):
        date_suffix = re.match(
            r"\s*(?:,\s*|\s+)?(?:19|20)\d{2}(?:\s*[-\u2013]\s*(?:19|20)\d{2})?",
            after,
        )
        if date_suffix:
            end += date_suffix.end()

    if _query_has_any(query, _CLAUSE_TERMS):
        candidate_span = segment[start:end].strip()
        segment_norm = _norm_for_match(segment)
        candidate_norm = _norm_for_match(candidate_span)
        if (
            candidate_span
            and segment_norm.startswith(candidate_norm)
            and len(candidate_span) < len(segment)
        ):
            return _strip_terminal_punctuation(segment).strip()

    return segment[start:end].strip()


def _select_context_form(question: str, query: str, candidate: str) -> str | None:
    candidate = (candidate or "").strip()
    if not candidate:
        return None
    cand_tokens = _tokenize_spans(candidate)
    if not cand_tokens:
        return None
    cand_norms = [token["norm"] for token in cand_tokens]

    best_span: str | None = None
    best_score = -1.0
    best_key: str | None = None
    ties = 0

    for segment in _split_segments(question):
        seg_tokens = _tokenize_spans(segment)
        if not seg_tokens:
            continue

        variants: list[tuple] = []
        full_window = _window_for_tokens(seg_tokens, cand_norms)
        if full_window is not None:
            variants.append((full_window, 1.0, "full"))
        else:
            seg_norm_set = {token["norm"] for token in seg_tokens}
            filtered = [norm for norm in cand_norms if norm in seg_norm_set]
            coverage = len(filtered) / max(1, len(cand_norms))
            if filtered and coverage >= 0.5:
                filtered_window = _window_for_tokens(seg_tokens, filtered)
                if filtered_window is not None:
                    variants.append((filtered_window, coverage, "filtered"))

        for window, coverage, mode in variants:
            start_idx, end_idx, match_type = window
            span = _expand_context_window(segment, seg_tokens, start_idx, end_idx, query)
            if not span:
                continue
            if mode == "full" and match_type == "exact":
                score = 4.0
            elif mode == "full" and match_type == "gapped":
                score = 3.8
            elif mode == "filtered" and match_type == "exact":
                score = 2.5 + coverage
            else:
                score = 2.3 + coverage
            score -= min(0.5, len(span) / 500.0)

            key = span.lower()
            if score > best_score + 1e-9:
                best_score = score
                best_span = span
                best_key = key
                ties = 1
            elif abs(score - best_score) < 1e-9:
                if key != best_key:
                    ties += 1

    if best_span is None or ties > 1:
        return None
    return _strip_terminal_punctuation(best_span).strip()


async def _side_extract_answer(question: str, candidate: str, ctx: Context) -> str | None:
    prompt = (
        "You are an answer canonicalizer. The original task below contains a question "
        "and any supplied context. A model produced the candidate final answer. Return "
        "only the final short answer exactly as requested. Prefer the exact wording of "
        "the supplied context when it provides a more complete or more minimal official "
        "form (full names, titles, numeric/date expressions, or descriptive clauses). "
        "Do not add explanations, citations, sentence prefixes, or terminal punctuation.\n\n"
        f"ORIGINAL TASK:\n{question}\n\n"
        f"CANDIDATE ANSWER:\n{candidate}\n\n"
        "EXACT ANSWER:"
    )
    result = await ctx.side_text(
        prompt, purpose="answer_canonicalization", max_tokens=200
    )
    if not result:
        return None
    extracted = _strip_wrapper_formatting(result)
    extracted = _strip_sentence_prefixes(extracted)
    extracted = _strip_terminal_punctuation(extracted).strip()
    if not extracted:
        return None
    lines = [line.strip() for line in extracted.splitlines() if line.strip()]
    if lines:
        extracted = lines[0]
    return extracted or None


async def _canonicalize_answer(question: str, candidate: str, ctx: Context) -> str:
    original = candidate
    if not candidate.strip():
        return candidate

    cleaned = _strip_wrapper_formatting(candidate)
    cleaned = _strip_sentence_prefixes(cleaned)
    cleaned = _strip_terminal_punctuation(cleaned)

    query = _question_query(question)
    cleaned = _strip_leading_locative(cleaned, query, question)
    cleaned = _strip_trailing_category(cleaned, query, question)
    cleaned = _strip_terminal_punctuation(cleaned)

    deterministic = _select_context_form(question, query, cleaned)
    if deterministic is not None:
        canonical = deterministic
        method = "deterministic"
    else:
        side = await _side_extract_answer(question, cleaned, ctx)
        if side is not None:
            canonical = side
            method = "side_model"
        else:
            canonical = cleaned
            method = "fallback"

    canonical = _strip_terminal_punctuation(_strip_wrapper_formatting(canonical)).strip()
    if not canonical:
        canonical = cleaned or original

    ctx.trace.event(
        "answer_canonicalization",
        before=original,
        after=canonical,
        method=method,
    )
    return canonical

